  add('foundations', 'basics', [
    ['ceteris', 'Klauzula ceteris paribus', 'Założenie, że podczas badania wpływu jednego czynnika na dane zjawisko pozostałe istotne czynniki pozostają niezmienione.', 'Wzrost ceny powoduje ruch po danej krzywej popytu; zmiana dochodu może przesunąć całą krzywą.'],
    ['post-hoc', 'Błąd post hoc ergo propter hoc', 'Błąd rozumowania polegający na uznaniu, że skoro zdarzenie B nastąpiło po A, to A musiało spowodować B. Sama kolejność w czasie nie dowodzi przyczynowości.', 'Przykład: spadek bezrobocia po zmianie ministra nie jest sam w sobie dowodem skuteczności jego działań.'],
    ['ppf', 'Krzywa transformacji', 'Granica możliwości produkcyjnych: zbiór maksymalnych osiągalnych kombinacji produkcji dwóch dóbr przy danych zasobach, technologii i ich efektywnym wykorzystaniu.', 'Punkt wewnątrz oznacza niewykorzystane możliwości; punkt poza granicą jest obecnie nieosiągalny. Wypukłość zbioru możliwości wiąże się z rosnącym kosztem alternatywnym.', 'PPF PPC krzywa możliwości produkcyjnych'],
    ['ownership', 'Własność ekonomiczna i prawna', 'W sensie ekonomicznym własność oznacza faktyczne sprawowanie kontroli nad zasobem i czerpanie z niego korzyści. W sensie prawnym jest prawem do korzystania z rzeczy i rozporządzania nią w granicach prawa.', 'Kontrola ekonomiczna i tytuł prawny nie muszą należeć do tej samej osoby; uprawnienia właściciela nie są nieograniczone.'],
    ['positive', 'Ekonomia pozytywna', 'Opisuje i wyjaśnia funkcjonowanie gospodarki, formułując twierdzenia poddające się sprawdzaniu na podstawie danych lub rozumowania.', 'Twierdzenie pozytywne może być fałszywe. „Pozytywne” nie oznacza „korzystne”.'],
    ['normative', 'Ekonomia normatywna', 'Formułuje oceny i zalecenia dotyczące tego, jak gospodarka powinna funkcjonować. Opiera się na przyjętych wartościach i kryteriach oceny.', 'Przykład: „Państwo powinno zmniejszyć nierówności dochodowe”.'],
    ['opportunity', 'Koszt alternatywny', 'Wartość najlepszej dostępnej możliwości, z której trzeba zrezygnować, dokonując danego wyboru.', 'Nie jest sumą wartości wszystkich odrzuconych możliwości.'],
    ['economic-good', 'Dobro ekonomiczne', 'Dobro rzadkie w stosunku do potrzeb: wykorzystanie go w jednym celu ogranicza dostępność dla innych zastosowań i wiąże się z kosztem alternatywnym.', 'Zerowa cena dla użytkownika nie oznacza, że dobro jest wolne.'],
    ['free-good', 'Dobro wolne', 'Dobro dostępne w danym miejscu i czasie w ilości wystarczającej wobec potrzeb, przez co jego wykorzystanie nie wymaga rezygnacji z alternatywnego zastosowania rzadkich zasobów.', 'To samo dobro może być wolne w jednym kontekście, a ekonomiczne w innym.']
  ]);
  add('foundations', 'market', [
    ['seller-market', 'Rynek producenta', 'Rynek sprzedawcy: sytuacja, w której przy danej cenie ilość pożądana przez nabywców przewyższa ilość oferowaną, co wzmacnia pozycję sprzedawców.', 'To określenie sytuacji niedoboru, a nie synonim monopolu.', 'rynek sprzedawcy'],
    ['buyer-market', 'Rynek konsumenta', 'Rynek nabywcy: sytuacja, w której przy danej cenie ilość oferowana przewyższa ilość pożądaną przez nabywców, co wzmacnia pozycję kupujących.', '', 'rynek nabywcy'],
    ['demand-law', 'Prawo popytu', 'Ceteris paribus wzrost ceny dobra zazwyczaj zmniejsza wielkość popytu na to dobro, a spadek ceny ją zwiększa.', 'Chodzi o wielkość popytu przy danej cenie, nie o przesunięcie krzywej. Dobro Giffena jest szczególnym wyjątkiem.'],
    ['supply-law', 'Prawo podaży', 'Ceteris paribus wzrost ceny dobra zazwyczaj zwiększa wielkość jego podaży, a spadek ceny ją zmniejsza.', 'Warunkiem typowej reakcji jest możliwość dostosowania produkcji; nie każda krzywa podaży musi być rosnąca.'],
    ['consumer-surplus', 'Nadwyżka konsumenta', 'Różnica między maksymalną kwotą, którą nabywcy są skłonni zapłacić za zakupione jednostki dobra, a faktycznym wydatkiem na te jednostki.', 'Na standardowym wykresie: pole pod krzywą popytu i nad ceną, do wielkości zakupu.'],
    ['producer-surplus', 'Nadwyżka producenta', 'Różnica między wpływami ze sprzedaży a minimalnym wynagrodzeniem, przy którym sprzedawcy są skłonni dostarczyć sprzedane jednostki dobra.', 'W standardowej analizie krótkiego okresu PS = TR − VC, a zysk = PS − FC. Nadwyżka nie jest więc na ogół zyskiem.']
  ]);
  add('consumer', 'elasticity', [
    ['demand-elasticity', 'Elastyczność cenowa popytu', 'Stosunek względnej zmiany ilości nabywanej do względnej zmiany ceny tego samego dobra, ceteris paribus. Punktowo: E = (dQd/dP) · P/Qd.', 'Zwykle E < 0. Klasyfikacja korzysta z |E|: ponad 1 — popyt elastyczny, poniżej 1 — nieelastyczny, 1 — jednostkowy. Dla zmian skończonych podaj metodę, np. łukową.'],
    ['supply-elasticity', 'Elastyczność cenowa podaży', 'Stosunek względnej zmiany ilości oferowanej do względnej zmiany ceny tego samego dobra, przy pozostałych warunkach niezmienionych. Punktowo: Es = (dQs/dP) · P/Qs.', 'Zwykle jest nieujemna; zależy m.in. od czasu dostosowania i dostępności mocy produkcyjnych.'],
    ['income-elasticity', 'Elastyczność dochodowa popytu', 'Stosunek względnej zmiany ilości nabywanej do względnej zmiany dochodu konsumenta, przy niezmienionych cenach i preferencjach: Ey = (dQ/dY) · Y/Q.', 'Ey < 0: dobro podrzędne; Ey > 0: normalne; 0 < Ey < 1: podstawowe; Ey > 1: luksusowe.', 'elastyczność dochodowa'],
    ['cross-demand', 'Elastyczność mieszana popytu', 'Mierzy względną zmianę wielkości popytu na dobro X w reakcji na względną zmianę ceny dobra Y, ceteris paribus: Exy = (∂Qx/∂Py) · Py/Qx.', 'Dodatnia zwykle oznacza substytuty w popycie, ujemna — dobra komplementarne; zerowa — brak lokalnej reakcji.', 'elastyczność krzyżowa popytu'],
    ['cross-supply', 'Elastyczność mieszana podaży', 'Mierzy względną zmianę ilości oferowanej dobra X w reakcji na względną zmianę ceny innego dobra Y, przy pozostałych warunkach stałych: Esxy = (∂Qsx/∂Py) · Py/Qsx.', 'Ujemna może wskazywać konkurencję produktów o te same zasoby, dodatnia — produkcję łączną. Nie stosuj tu automatycznie interpretacji znaków z popytu.', 'elastyczność krzyżowa podaży'],
    ['flexibility', 'Fleksybilność cen', 'Miara reakcji ceny równowagi na zmianę popytu przy pozostałych warunkach stałych. Przy rosnącej krzywej podaży wzrost popytu prowadzi typowo do wzrostu ceny równowagi.', 'Nie myl z cenową elastycznością popytu, w której to wielkość popytu reaguje na zmianę własnej ceny. W zadaniu sprawdź, czy autor używa nazwy jakościowo, czy definiuje konkretny iloraz zmian procentowych.'],
    ['expansibility', 'Ekspansybilność cen', 'Miara reakcji ceny równowagi na zmianę podaży przy pozostałych warunkach stałych. Przy opadającej krzywej popytu wzrost podaży prowadzi typowo do spadku ceny równowagi.', 'Nie myl z cenową elastycznością podaży, w której to wielkość podaży reaguje na zmianę własnej ceny. W zadaniu sprawdź konwencję znaku i dokładną definicję współczynnika.'],
    ['inferior', 'Dobro podrzędne', 'Dobro, którego wielkość popytu maleje wraz ze wzrostem dochodu konsumenta, ceteris paribus. Jego dochodowa elastyczność popytu jest ujemna.', 'Nie oznacza złej jakości. Nie każde dobro podrzędne jest dobrem Giffena.', 'dobro niższego rzędu'],
    ['normal', 'Dobro normalne', 'Dobro, którego wielkość popytu rośnie wraz ze wzrostem dochodu, ceteris paribus; ma dodatnią dochodową elastyczność popytu.', 'W tej klasyfikacji dobra normalne obejmują podstawowe i luksusowe.'],
    ['necessity', 'Dobro podstawowe', 'W klasyfikacji dochodowej: dobro normalne, na które popyt rośnie mniej niż proporcjonalnie do dochodu, czyli 0 < Ey < 1.', 'Przy stałej cenie jego udział w wydatkach maleje, gdy dochód rośnie. Ey = 1 to granica klasyfikacji.'],
    ['luxury', 'Dobro luksusowe', 'Dobro, na które popyt rośnie bardziej niż proporcjonalnie do dochodu, ceteris paribus: Ey > 1.', 'Sama wysoka cena ani efekt prestiżu nie stanowią tej definicji.'],
    ['engel', 'Prawo Engla i krzywa Engla', 'Prawo Engla: wraz ze wzrostem dochodu udział wydatków na żywność w wydatkach gospodarstwa na ogół maleje. Krzywa Engla pokazuje zależność ilości nabywanego dobra od dochodu przy stałych cenach i preferencjach.', 'Wydatki na żywność mogą jednocześnie rosnąć kwotowo. Historyczne rozszerzenia o inne kategorie wydatków są uogólnieniami empirycznymi, nie uniwersalnymi prawami.', 'prawa Engla krzywa Engla']
  ]);
  add('consumer', 'consumer', [
    ['indifference', 'Krzywa obojętności', 'Zbiór koszyków konsumpcyjnych dających konsumentowi ten sam poziom użyteczności. Jej kształt odzwierciedla preferencje.', 'Dla dwóch pożądanych dóbr zwykle opada; wypukłość wynika z preferowania zróżnicowanych koszyków. Nie każda krzywa jest gładka ani ściśle wypukła.'],
    ['perfect-substitutes', 'Dobra doskonale substytucyjne', 'Dobra, które konsument jest gotów wymieniać w stałej proporcji niezależnie od składu koszyka. Dla U = ax + by krzywe obojętności są prostymi, a MRS = a/b.', 'Optimum zwykle jest narożne; gdy a/b = Px/Py, wszystkie koszyki na linii budżetu dają tę samą użyteczność.'],
    ['perfect-complements', 'Dobra doskonale komplementarne', 'Dobra wykorzystywane w stałej proporcji; nadmiar jednego bez drugiego nie zwiększa użyteczności. Funkcja U = min(ax, by) daje krzywe obojętności w kształcie litery L.', 'W optimum przy dodatnich cenach ax = by; w załamaniu nie stosuje się warunku styczności z MRS.'],
    ['neutral-good', 'Dobro obojętne', 'Dobro, którego ilość nie wpływa na użyteczność konsumenta, przy pozostałych ilościach stałych.', 'Jeśli X jest obojętne, a Y pożądane, przy X na osi poziomej krzywe obojętności są poziome. Nie myl z niezależnością dwóch dóbr w popycie.'],
    ['budget', 'Linia ograniczenia budżetowego', 'Zbiór koszyków, na które konsument wydaje cały dochód: Px · x + Py · y = I. Przy x na osi poziomej nachylenie wynosi −Px/Py.', 'Zbiór dostępny spełnia nierówność Px · x + Py · y ≤ I. Wzrost dochodu przy stałych cenach przesuwa linię równolegle.'],
    ['mrs', 'Krańcowa stopa substytucji', 'Ilość dobra Y, z której konsument może zrezygnować za dodatkową, bardzo małą ilość X bez zmiany użyteczności. Dla gładkich preferencji i dóbr pożądanych: MRSxy = MUx/MUy = −dy/dx.', 'Tutaj stosujemy dodatnią wartość MRS; samo nachylenie krzywej jest ujemne.', 'MRS'],
    ['substitution', 'Efekt substytucyjny', 'Część reakcji popytu na zmianę ceny wynikająca ze zmiany relacji cen, po skompensowaniu zmiany siły nabywczej. Konsument zastępuje dobro relatywnie droższe tańszym.', 'Kompensacja Hicksa zachowuje użyteczność; kompensacja Słuckiego — możliwość zakupu pierwotnego koszyka.'],
    ['income-effect', 'Efekt dochodowy', 'Część reakcji popytu na zmianę ceny wynikająca ze zmiany realnej siły nabywczej dochodu, po wyodrębnieniu efektu substytucyjnego.', 'Po obniżce ceny zwiększa zakup dobra normalnego, a zmniejsza zakup dobra podrzędnego. Dochód nominalny może być niezmieniony.'],
    ['giffen', 'Dobro Giffena', 'Szczególne dobro podrzędne, dla którego wzrost własnej ceny zwiększa wielkość popytu, ceteris paribus: przeciwny efekt dochodowy jest silniejszy niż efekt substytucyjny.', 'Nie wynika z prestiżu. Ujemna elastyczność dochodowa jest konieczna, ale niewystarczająca.'],
    ['veblen', 'Dobro Veblena', 'Dobro kupowane m.in. dla prestiżu, którego wyższa cena może zwiększać atrakcyjność jako oznaki statusu i przez to skłonność do zakupu.', 'Wyjaśnienie opiera się na funkcji sygnalizacyjnej ceny, nie na mechanizmie dochodowym Giffena.'],
    ['snob', 'Efekt snoba', 'Zmniejszenie popytu danej osoby na dobro wskutek upowszechnienia jego konsumpcji wśród innych osób, ponieważ nabywca ceni wyjątkowość.', 'Dotyczy wpływu popularności dobra; efekt Veblena dotyczy prestiżu związanego z ceną.']
  ]);
  add('firm', 'production', [
    ['diminishing', 'Prawo malejących przychodów', 'Przy stałej technologii i przynajmniej jednym stałym czynniku produkcji zwiększanie nakładu czynnika zmiennego od pewnego poziomu przynosi coraz mniejsze przyrosty produktu całkowitego.', 'Maleje produkt krańcowy; produkt całkowity nie musi maleć. Nie myl ze spadającymi przychodami ze skali.', 'prawo malejącej produktywności krańcowej'],
    ['production-function', 'Funkcja produkcji', 'Zależność określająca maksymalny produkt możliwy do uzyskania z danych ilości czynników przy danej technologii, np. Q = f(K, L).', 'Opisuje możliwości techniczne, a nie wpływy ze sprzedaży.'],
    ['isoquant', 'Izokwanta', 'Zbiór kombinacji nakładów czynników, np. pracy i kapitału, które pozwalają wytworzyć tę samą ilość produktu przy danej technologii.', 'Czynniki doskonale substytucyjne dają izokwanty liniowe; doskonale komplementarne — w kształcie L.'],
    ['isocost', 'Izokoszta', 'Zbiór kombinacji czynników o jednakowym koszcie przy danych cenach: C = wL + rK. Przy L na osi poziomej nachylenie wynosi −w/r.', 'w to cena jednostki pracy, r — cena usług jednostki kapitału.'],
    ['producer-optimum', 'Optimum producenta — dobór nakładów', 'Kombinacja czynników minimalizująca koszt wytworzenia zadanej produkcji, równoważnie maksymalizująca produkcję przy zadanym budżecie. Dla wewnętrznego, gładkiego rozwiązania: MPL/MPK = w/r.', 'Warunek styczności izokwanty i izokoszty nie obejmuje automatycznie rozwiązań narożnych ani załamań. W szerszym znaczeniu optimum producenta może oznaczać maksimum zysku.'],
    ['mrts', 'Krańcowa techniczna stopa substytucji', 'Ilość kapitału, którą można zastąpić dodatkową, bardzo małą ilością pracy bez zmiany produkcji: MRTSLK = MPL/MPK = −dK/dL wzdłuż gładkiej izokwanty.', 'To wymiana czynników produkcji; MRS odnosi się do dóbr konsumpcyjnych.', 'MRTS KTSS'],
    ['mrt', 'Krańcowa stopa transformacji', 'Ilość dobra Y, z której produkcji trzeba zrezygnować, aby na granicy możliwości produkcyjnych uzyskać dodatkową, bardzo małą ilość X: MRTxy = −dY/dX.', 'To krańcowy koszt alternatywny produkcji X wyrażony w jednostkach Y; w standardowym modelu MRTxy = MCx/MCy.', 'MRT KST'],
    ['returns-scale', 'Przychody ze skali produkcji', 'Opisują zmianę produktu po proporcjonalnym zwiększeniu wszystkich nakładów. Są rosnące, stałe lub malejące, gdy produkt rośnie odpowiednio bardziej niż, dokładnie tak jak lub mniej niż nakłady.', 'To relacja technologiczna. Kosztowe korzyści skali dotyczą kosztu przeciętnego; nie należy bezwarunkowo utożsamiać tych pojęć.'],
    ['economies', 'Korzyści skali produkcji', 'Spadek długookresowego kosztu przeciętnego wraz ze wzrostem produkcji, np. dzięki specjalizacji i rozłożeniu niektórych kosztów na większą liczbę jednostek.', 'Rozpatruje się możliwość dostosowania wszystkich czynników.'],
    ['diseconomies', 'Niekorzyści skali produkcji', 'Wzrost długookresowego kosztu przeciętnego wraz ze wzrostem produkcji, np. wskutek rosnących trudności koordynacji.', 'Nie są tym samym co krótkookresowa malejąca produktywność czynnika zmiennego.'],
    ['constant-scale', 'Stałe korzyści skali produkcji', 'Określenie stałego długookresowego kosztu przeciętnego przy zwiększaniu produkcji: koszt całkowity rośnie proporcjonalnie do produktu.', 'Precyzyjniej: brak korzyści i niekorzyści skali. Stałe przychody ze skali to odrębna własność funkcji produkcji.'],
    ['factors', 'Czynniki produkcji i ich dochody', 'Klasyczne czynniki to praca, ziemia i kapitał; często wyodrębnia się przedsiębiorczość. Pracy odpowiada płaca, ziemi renta gruntowa, kapitałowi dochód z jego udostępnienia, a przedsiębiorczości zysk.', 'W szkolnym schemacie kapitał — procent. Cena usług kapitału rzeczowego jest jednak stawką najmu, a procent dotyczy kapitału finansowego.'],
    ['total-product', 'Produkt całkowity', 'Łączna ilość wytworzonego produktu przy określonych nakładach czynników i danej technologii: TP = Q.', 'To wielkość produkcji, nie utarg.', 'TP'],
    ['average-product', 'Produkt przeciętny', 'Wielkość produkcji przypadająca na jednostkę danego czynnika: dla pracy APL = Q/L, przy L > 0.', 'Nie myl przeciętnej produktywności z produktem kolejnej jednostki czynnika.', 'AP'],
    ['marginal-product', 'Produkt krańcowy', 'Przyrost produkcji wynikający ze zwiększenia nakładu danego czynnika przy stałych pozostałych nakładach. Dla pracy: MPL = ∂Q/∂L, w ujęciu dyskretnym ΔQ/ΔL.', 'Spadek MP nie oznacza jeszcze spadku TP; TP maleje dopiero przy ujemnym MP.', 'MP'],
    ['explicit', 'Koszty jawne', 'Koszty wykorzystania zasobów nabywanych na rynku, z którymi wiążą się wydatki pieniężne, np. wynagrodzenia pracowników i zakupy materiałów.', 'Moment zapłaty nie musi pokrywać się z momentem ujęcia kosztu w rachunkowości.'],
    ['implicit', 'Koszty ukryte', 'Koszty alternatywne wykorzystania własnych zasobów, za które przedsiębiorstwo nie dokonuje odrębnej płatności, np. utracone wynagrodzenie właściciela pracującego we własnej firmie.', 'To wartość najlepszych utraconych zastosowań, nie dowolnie oszacowane wydatki.', 'koszty niejawne implicite'],
    ['economic-cost', 'Koszty ekonomiczne', 'Łączne koszty alternatywne zasobów użytych w działalności, obejmujące koszty jawne oraz ukryte. Zysk ekonomiczny to utarg pomniejszony o te koszty.', 'Zerowy zysk ekonomiczny obejmuje normalne wynagrodzenie własnych zasobów.'],
    ['total-cost', 'Koszt całkowity', 'Suma wszystkich kosztów poniesionych dla danej wielkości produkcji. W krótkim okresie: TC = FC + VC.', 'W zadaniu ustal, czy chodzi o koszty księgowe, czy ekonomiczne.', 'TC'],
    ['average-cost', 'Koszt przeciętny', 'Koszt całkowity przypadający na jednostkę produktu: ATC = TC/Q dla Q > 0. ATC = AFC + AVC.', 'AFC = FC/Q, AVC = VC/Q. Koszt przeciętny nie jest kosztem kolejnej jednostki.', 'AC ATC'],
    ['marginal-cost', 'Koszt krańcowy', 'Przyrost kosztu całkowitego na dodatkową jednostkę produkcji: MC = ΔTC/ΔQ, a dla różniczkowalnej funkcji MC = dTC/dQ.', 'Przy stałym FC: MC = dVC/dQ. Gdy MC < ATC, ATC maleje; gdy MC > ATC, ATC rośnie.', 'MC'],
    ['fixed-cost', 'Koszt stały', 'Koszt, którego wielkość w krótkim okresie i danym zakresie zdolności wytwórczych nie zależy od bieżącej wielkości produkcji; jest ponoszony również przy Q = 0.', 'Nie każdy koszt stały jest utopiony. Płaca lub czynsz mogą być stałe bądź zmienne zależnie od umowy i horyzontu.', 'FC'],
    ['variable-cost', 'Koszt zmienny', 'Koszt zależny od wielkości produkcji, np. zużytych materiałów. W standardowym krótkookresowym modelu VC(0) = 0.', '„Zmienny” nie oznacza, że koszt musi być proporcjonalny do produkcji.', 'VC'],
    ['short-run', 'Krótki okres w ekonomii', 'W teorii przedsiębiorstwa: horyzont, w którym przynajmniej jeden czynnik produkcji pozostaje stały.', 'Nie określa go sztywna liczba miesięcy; w makroekonomii krótki okres często oznacza horyzont niepełnego dostosowania cen i płac.'],
    ['long-run', 'Długi okres w ekonomii', 'W teorii przedsiębiorstwa: horyzont pozwalający zmieniać wszystkie nakłady oraz wejść do gałęzi lub ją opuścić.', 'Nie wymaga zmiany technologii. W makroekonomii zwykle zakłada pełniejsze dostosowanie cen i płac.']
  ]);
  add('markets', 'competition', [
    ['economic-optimum', 'Optimum ekonomiczne przedsiębiorstwa', 'Wielkość produkcji zapewniająca najwyższy zysk ekonomiczny, czyli największą różnicę TR − TC. Dla wewnętrznego, różniczkowalnego rozwiązania warunkiem koniecznym jest MR = MC.', 'Trzeba sprawdzić maksimum oraz możliwość Q = 0. Typowo MC przecina MR od dołu; samo MR = MC nie wystarcza.'],
    ['technical-optimum', 'Optimum techniczne (technologiczne) w teorii kosztów', 'Wielkość produkcji minimalizująca przeciętny koszt całkowity. Przy gładkim, wewnętrznym minimum zachodzi MC = ATC.', 'Nazewnictwo zależy od modelu: maksimum produktu przeciętnego czynnika spełnia MP = AP. Minimum ATC nie jest na ogół maksimum zysku; odczytuj kontekst zadania.', 'optimum technologiczne optimum techniczne'],
    ['short-equilibrium', 'Krótkookresowa równowaga gałęzi wolnokonkurencyjnej', 'Stan, w którym popyt rynkowy równa się podaży, liczba firm jest dana, a każda czynna firma wybiera produkcję maksymalizującą zysk przy cenie rynkowej, typowo P = MC na rosnącym odcinku MC.', 'Firmy mogą osiągać zysk lub stratę; kontynuują produkcję, jeśli utarg pokrywa koszty możliwe do uniknięcia, w standardowym modelu koszty zmienne.'],
    ['long-equilibrium', 'Długookresowa równowaga gałęzi wolnokonkurencyjnej', 'Stan równowagi rynku bez bodźców do wejścia ani wyjścia firm. W standardowym modelu identycznych firm, swobodnego wejścia i stałych cen czynników: P = MR = LMC = min LAC, a zysk ekonomiczny jest zerowy.', 'Nie oznacza to zerowego zysku księgowego. Przy zróżnicowaniu firm lub ograniczonych zasobach mogą występować renty.'],
    ['shutdown', 'Cena zamknięcia przedsiębiorstwa', 'W standardowym krótkookresowym modelu firmy konkurencyjnej cena równa minimum przeciętnego kosztu zmiennego: P = min AVC. Poniżej tej ceny opłaca się wstrzymać produkcję.', 'Przy równości firma jest obojętna między produkcją w minimum AVC a zamknięciem. Wyjście z rynku w długim okresie wiąże się z pokryciem wszystkich kosztów.'],
    ['total-revenue', 'Utarg całkowity', 'Łączne wpływy ze sprzedaży produktu: TR = P · Q przy jednej cenie sprzedaży; ogólniej suma wpływów ze wszystkich sprzedanych jednostek.', 'Utarg to przychód, nie zysk.', 'TR przychód całkowity'],
    ['average-revenue', 'Utarg przeciętny', 'Utarg przypadający na sprzedaną jednostkę: AR = TR/Q, dla Q > 0. Przy jednej cenie AR = P.', 'Równość AR = P nie jest ograniczona do konkurencji doskonałej.', 'AR przychód przeciętny'],
    ['marginal-revenue', 'Utarg krańcowy', 'Przyrost utargu całkowitego związany z dodatkową jednostką sprzedaży: MR = ΔTR/ΔQ, a dla gładkiej funkcji MR = dTR/dQ.', 'U cenobiorcy MR = P; przy opadającym popycie i jednej cenie MR < P.', 'MR przychód krańcowy']
  ]);
  add('markets', 'monopoly', [
    ['natural-monopoly', 'Monopol naturalny', 'Sytuacja, w której jeden producent może zaspokoić cały popyt rynkowy przy niższym koszcie całkowitym niż dowolny podział tej produkcji między kilka firm — koszt jest subaddytywny w istotnym zakresie.', 'Trwałe korzyści skali w zakresie popytu są typowym powodem, lecz subaddytywność jest kryterium ogólniejszym.'],
    ['cournot', 'Punkt Cournota', 'W standardowej analizie monopolu punkt na krzywej popytu wskazujący cenę i ilość maksymalizujące zysk: najpierw wyznacza się Q z MR = MC i sprawdza maksimum, a potem odczytuje P z popytu.', 'Nie jest to samo przecięcie MR i MC ani równowaga duopolu Cournota. Nie utożsamiaj go z maksimum utargu (MR = 0).'],
    ['discrimination', 'Dyskryminacja cenowa', 'Różnicowanie cen tego samego dobra między nabywcami lub transakcjami, którego nie wyjaśniają różnice kosztów obsługi.', 'Wymaga pewnej siły rynkowej oraz ograniczenia odsprzedaży; nie każda różnica ceny jest dyskryminacją.'],
    ['discrimination-1', 'Dyskryminacja cenowa pierwszego stopnia', 'Pobieranie za każdą jednostkę maksymalnej ceny, jaką konkretny nabywca jest gotów za nią zapłacić. W modelu doskonałym sprzedawca przejmuje całą nadwyżkę konsumentów.', 'Wymaga szczegółowej wiedzy o gotowości do zapłaty i możliwości uniemożliwienia arbitrażu.'],
    ['discrimination-2', 'Dyskryminacja cenowa drugiego stopnia', 'Oferowanie tego samego menu cen i wariantów wszystkim klientom, którzy sami wybierają opcję, np. taryfę zależną od ilości albo pakietu.', 'Istotna jest samoselekcja. Różnica cen musi wykraczać poza różnice kosztów.'],
    ['discrimination-3', 'Dyskryminacja cenowa trzeciego stopnia', 'Ustalanie różnych cen dla rozpoznawalnych grup klientów o różnej elastyczności popytu, przy ograniczeniu odsprzedaży.', 'Przy jednakowym koszcie krańcowym optymalna cena jest wyższa w grupie o mniejszej bezwzględnej elastyczności popytu.'],
    ['bilateral', 'Monopol bilateralny', 'Rynek, na którym jedyny sprzedawca negocjuje z jedynym nabywcą. Występują jednocześnie monopol po stronie podaży i monopson po stronie popytu.', 'Ceny i ilości zależą m.in. od siły przetargowej oraz reguł negocjacji; sama struktura nie wyznacza jednej ceny.'],
    ['lerner', 'Indeks Lernera', 'Miara narzutu ceny ponad koszt krańcowy w relacji do ceny: L = (P − MC)/P. W konkurencji doskonałej L = 0.', 'Dla monopolisty maksymalizującego zysk przy jednej cenie i rozwiązaniu wewnętrznym L = −1/Ed, gdzie Ed < 0. Nie jest udziałem w rynku.'],
    ['hhi', 'Wskaźnik Herfindahla–Hirschmana', 'Miara koncentracji rynku będąca sumą kwadratów udziałów rynkowych wszystkich firm: HHI = Σ si².', 'Przy udziałach procentowych monopol daje 10 000, przy ułamkach — 1. Dla n równych firm HHI = 10 000/n w skali procentowej; sama koncentracja nie dowodzi nadużycia.', 'HHI Herfindahla Hirschmana']
  ]);
  add('markets', 'labor', [
    ['monopsony', 'Monopson na rynku pracy', 'Rynek z jednym nabywcą pracy. W prostym modelu z jedną stawką płac i rosnącą podażą pracy krańcowy koszt zatrudnienia przewyższa płacę; firma wybiera zatrudnienie z MFC = MRPL.', 'Względem porównywalnego rynku konkurencyjnego prowadzi to zwykle do niższej płacy i zatrudnienia.'],
    ['labor-demand', 'Popyt na pracę', 'Zależność między stawką płacy a ilością pracy, którą pracodawcy chcą zatrudnić. Jest pochodny wobec popytu na wytwarzany produkt.', 'Firma przy konkurencyjnym rynku pracy porównuje płacę z MRPL = MR · MPL; gdy także rynek produktu jest konkurencyjny, MRPL = P · MPL.'],
    ['labor-supply', 'Podaż pracy', 'Zależność między płacą a ilością pracy, którą ludzie chcą zaoferować. Wybór jednostki obejmuje kompromis między konsumpcją a czasem wolnym.', 'Wyższa płaca daje efekt substytucyjny sprzyjający pracy i, przy normalnym czasie wolnym, przeciwny efekt dochodowy; indywidualna krzywa może zawracać.'],
    ['efficiency-wage', 'Płace efektywnościowe', 'Płace ustalane przez pracodawcę powyżej poziomu równoważącego rynek, aby zwiększyć wydajność, ograniczyć rotację lub uchylanie się od pracy albo przyciągnąć lepszych kandydatów.', 'Mogą podtrzymywać bezrobocie mimo gotowości części osób do pracy za niższą płacę.'],
    ['involuntary', 'Bezrobocie przymusowe', 'Sytuacja osoby gotowej podjąć pracę za obowiązującą płacę i na danych warunkach, która mimo poszukiwań nie może znaleźć zatrudnienia.', 'Nie jest tożsama wyłącznie z bezrobociem cyklicznym.'],
    ['voluntary', 'Bezrobocie dobrowolne', 'W ujęciu teoretycznym brak zatrudnienia wynikający z nieprzyjęcia dostępnej pracy na oferowanych warunkach, np. gdy płaca jest niższa od płacy progowej danej osoby.', 'Nie utożsamiaj z biernością zawodową ani automatycznie z całym bezrobociem frykcyjnym.']
  ]);
  add('welfare', 'public', [
    ['private-good', 'Dobro prywatne', 'Dobro, którego konsumpcja jest rywalizacyjna i z którego korzystania można skutecznie wykluczyć inne osoby.', 'Przykład: kanapka. Kryterium nie jest własność prywatnej firmy.'],
    ['public-good', 'Dobro publiczne', 'W czystej postaci dobro nierywalizacyjne w konsumpcji i niewykluczalne: korzystanie przez jedną osobę nie ogranicza korzystania przez innych, a ich wykluczenie jest niewykonalne lub zbyt kosztowne.', 'Nie każde dobro finansowane przez państwo jest dobrem publicznym.'],
    ['club-good', 'Dobro klubowe', 'Dobro, z którego można wykluczyć użytkowników, ale którego konsumpcja jest nierywalizacyjna przynajmniej do granicy przeciążenia.', 'Przykład: niezatłoczona płatna droga. Po przekroczeniu pojemności pojawia się rywalizacja.'],
    ['common-resource', 'Wspólny zasób', 'Zasób rywalizacyjny w wykorzystaniu, przy utrudnionym lub niemożliwym wykluczeniu użytkowników.', 'Przykład: łowisko o otwartym dostępie. Nie jest czystym dobrem publicznym.', 'wspólne zasoby'],
    ['free-rider', 'Problem gapowicza', 'Korzystanie z dobra lub wspólnego działania bez udziału w kosztach jego zapewnienia. Przy niewykluczalności osłabia bodźce do dobrowolnego finansowania dobra.', 'Może prowadzić do zbyt małej podaży dóbr publicznych.'],
    ['commons', 'Tragedia wspólnego pastwiska', 'Nadmierne wykorzystanie wspólnego zasobu, gdy użytkownik uwzględnia własną korzyść, ale pomija część kosztów, które jego działanie narzuca innym.', 'Nie jest nieuchronna: zasady wspólnotowe, egzekwowane limity lub prawa dostępu mogą ograniczyć nadmierną eksploatację.'],
    ['merit', 'Dobra społecznie pożądane i niepożądane', 'Dobra społecznie pożądane (merit goods) są oceniane jako konsumowane w zbyt małej ilości, np. z powodu niedoinformowania lub pomijania korzyści. Dobra niepożądane (demerit goods) — w nadmiernej ilości względem przyjętej oceny społecznej.', 'To kategoria normatywna, odrębna od podziału na dobra publiczne i prywatne. Przykłady: profilaktyka zdrowotna oraz używki.']
  ]);
  add('welfare', 'external', [
    ['pigou', 'Podatek Pigou', 'Podatek służący internalizacji ujemnego efektu zewnętrznego. W modelu pierwszego najlepszego rozwiązania stawka jednostkowa równa jest krańcowemu kosztowi zewnętrznemu przy społecznie optymalnym poziomie aktywności.', 'Nie chodzi o koszt zewnętrzny przeciętny ani koniecznie o koszt krańcowy przy dotychczasowej produkcji.'],
    ['coase', 'Twierdzenie Coase’a', 'Przy jasno określonych i egzekwowalnych prawach, zerowych kosztach transakcyjnych i możliwości negocjacji strony mogą uzgodnić efektywne rozwiązanie problemu efektów zewnętrznych.', 'Początkowy podział praw wpływa na podział korzyści. Niezależność końcowej alokacji od praw wymaga dodatkowych założeń, m.in. pominięcia efektów dochodowych.'],
    ['pareto', 'Efektywność w sensie Pareto', 'Stan, w którym nie można poprawić sytuacji choć jednej osoby bez pogorszenia sytuacji kogoś innego.', 'Nie oznacza sprawiedliwego ani równego podziału. Istnieje zwykle wiele alokacji efektywnych w sensie Pareto.', 'optimum Pareto']
  ]);
  add('welfare', 'games', [
    ['prisoner', 'Dylemat więźnia', 'Gra, w której indywidualnie racjonalny wybór strategii dominujących prowadzi do równowagi gorszej dla obu graczy niż dostępny wynik współpracy.', 'W grze jednorazowej standardowa równowaga jest nieefektywna w sensie Pareto; powtarzanie gry może zmienić bodźce.']
  ]);
  add('welfare', 'information', [
    ['adverse-selection', 'Selekcja negatywna', 'Problem ukrytych cech: strona lepiej poinformowana zna przed zawarciem transakcji swój typ lub jakość dobra, przez co skład uczestników rynku może pogarszać warunki wymiany.', 'Przykład: wspólna składka ubezpieczeniowa przyciąga przede wszystkim osoby o wysokim ryzyku.'],
    ['moral-hazard', 'Pokusa nadużycia', 'Problem ukrytego działania: po uzyskaniu ochrony lub zawarciu umowy strona zmienia zachowanie, bo nie ponosi w pełni skutków swoich decyzji, a druga strona nie może ich łatwo obserwować lub egzekwować.', 'Kluczowe jest zachowanie i bodźce, a nie ukryta cecha znana przed umową.', 'hazard moralny']
  ]);
  add('welfare', 'inequality', [
    ['horizontal-equity', 'Sprawiedliwość pozioma', 'Zasada jednakowego traktowania podmiotów znajdujących się w jednakowej istotnej sytuacji, np. o takiej samej zdolności podatkowej.', 'Wymaga określenia, które cechy uznajemy za istotne.'],
    ['vertical-equity', 'Sprawiedliwość pionowa', 'Zasada odpowiednio odmiennego traktowania podmiotów o różnej sytuacji, np. obciążania osób o większej zdolności podatkowej większym ciężarem.', 'Sama zasada nie wyznacza jednej konkretnej skali progresji.'],
    ['lorenz', 'Krzywa Lorenza', 'Wykres skumulowanego udziału ludności, uporządkowanej od najniższego do najwyższego dochodu, i odpowiadającego mu skumulowanego udziału w dochodzie całkowitym.', 'Przekątna obrazuje równość. Standardowa interpretacja zakłada nieujemne dochody i dodatnią ich sumę.'],
    ['gini', 'Wskaźnik Giniego', 'Miara nierówności: stosunek pola między linią równości a krzywą Lorenza do całego pola pod linią równości. Przy standardowych założeniach należy do przedziału od 0 do 1.', '0 oznacza równość, wartości bliskie 1 — silną koncentrację. Bywa podawany w skali 0–100; nie opisuje poziomu zamożności.']
  ]);
  add('macro', 'accounts', [
    ['gdp', 'Produkt krajowy brutto (PKB)', 'Wartość produkcji finalnej wytworzonej na terytorium gospodarczym kraju w danym okresie; równoważnie suma wartości dodanej powiększona o podatki od produktów i pomniejszona o dotacje do produktów.', 'Kryterium stanowi terytorium produkcji, nie obywatelstwo. W ujęciu wydatkowym PKB = C + I + G + X − M; G nie obejmuje transferów.'],
    ['gnp', 'Produkt narodowy brutto (PNB)', 'Tradycyjna kategoria odpowiadająca dochodowi narodowemu brutto: PKB powiększony o saldo dochodów pierwotnych otrzymanych przez rezydentów z zagranicy i wypłaconych nierezydentom.', 'Kryterium to rezydencja ekonomiczna, nie obywatelstwo; współcześnie stosuje się nazwę DNB.'],
    ['net-product', 'Produkt krajowy i narodowy netto', 'Produkt krajowy netto: PKN = PKB − zużycie kapitału trwałego. Tradycyjny produkt narodowy netto: PNN = PNB − zużycie kapitału trwałego.', 'Brutto/netto odnosi się do zużycia kapitału trwałego (amortyzacji w schemacie podręcznikowym), nie do odjęcia podatków.'],
    ['factor-prices', 'Ceny rynkowe i ceny czynników produkcji', 'W tradycyjnym rachunku produktu przejście od wyceny rynkowej do kosztu czynników wymaga odjęcia podatków od produkcji i importu oraz dodania odpowiednich dotacji.', 'Ceny czynników nie są cenami bazowymi: ceny bazowe zawierają inne podatki od produkcji netto. Nie myl tej konwersji z przejściem z brutto na netto.'],
    ['national-income', 'Dochód narodowy', 'W tradycyjnym schemacie podręcznikowym: produkt narodowy netto w cenach czynników produkcji, czyli suma dochodów czynników należących do rezydentów.', 'Współczesne rachunki stosują m.in. DNB i DNN w cenach rynkowych. Zawsze sprawdź, którą konwencję przyjmuje zadanie.'],
    ['disposable', 'Dochód rozporządzalny', 'Dochód dostępny na konsumpcję i oszczędności po uwzględnieniu bieżącej redystrybucji, m.in. podatków, składek i transferów. W prostym modelu gospodarstw: Yd = Y − T + TR.', 'T oznacza tu podatki brutto; jeśli T jest już podatkiem netto po transferach, nie dodawaj TR ponownie.']
  ]);
  add('macro', 'unemployment', [
    ['cyclical', 'Bezrobocie cykliczne', 'Składnik bezrobocia związany z wahaniami aktywności gospodarczej i odchyleniem produkcji od potencjału, zwłaszcza ze spadkiem popytu w recesji.', 'W prostym rozkładzie u = u naturalne + u cykliczne. Składnik cykliczny może być ujemny przy przegrzaniu gospodarki.'],
    ['frictional', 'Bezrobocie frykcyjne', 'Bezrobocie wynikające z czasu potrzebnego na znalezienie odpowiedniej pracy i dopasowanie pracowników do ofert, także przy normalnej koniunkturze.', 'Występuje m.in. przy zmianie pracy lub wejściu na rynek pracy.'],
    ['structural', 'Bezrobocie strukturalne', 'Bezrobocie wynikające z trwałego niedopasowania umiejętności, lokalizacji lub innych cech podaży pracy do struktury zapotrzebowania pracodawców.', 'Samo zwiększenie popytu globalnego może nie usunąć niedopasowania.'],
    ['natural-unemployment', 'Bezrobocie naturalne', 'Bezrobocie występujące przy produkcji na poziomie potencjalnym, bez składnika cyklicznego. W podstawowym ujęciu obejmuje bezrobocie frykcyjne i strukturalne.', 'Jego stopa zależy od instytucji i dopasowań; nie jest stałą przyrodniczą ani automatycznie społecznie optymalną stopą.'],
    ['actual-unemployment', 'Bezrobocie rzeczywiste', 'Faktycznie obserwowane bezrobocie według przyjętej definicji i metody pomiaru. Stopa bezrobocia to liczba bezrobotnych podzielona przez zasób siły roboczej, pomnożona przez 100%.', 'Siła robocza = pracujący + bezrobotni; osoby bierne zawodowo nie wchodzą do mianownika. W prostym rozkładzie stopa rzeczywista = naturalna + cykliczna.'],
    ['full-employment', 'Pełne zatrudnienie', 'Stan wykorzystania pracy odpowiadający produkcji potencjalnej, przy braku bezrobocia cyklicznego i bezrobociu na poziomie naturalnym.', 'Nie oznacza stopy bezrobocia równej zero.']
  ]);
  add('macro', 'prices', [
    ['deflator', 'Deflator PKB', 'Indeks cen produkcji finalnej wytworzonej w kraju: iloraz nominalnego i realnego PKB dla tego samego okresu, pomnożony przez 100 przy spójnej podstawie odniesienia.', 'Zakres obejmuje również dobra inwestycyjne i eksport, a nie obejmuje bezpośrednio importu; różni się od koszyka CPI.'],
    ['cpi', 'CPI — wskaźnik cen konsumpcyjnych', 'Miara zmiany cen reprezentatywnego koszyka dóbr i usług nabywanych przez gospodarstwa domowe, z wagami odzwierciedlającymi strukturę wydatków konsumpcyjnych.', 'Może obejmować importowane dobra konsumpcyjne. Stopa inflacji to procentowa zmiana indeksu, a nie sam jego poziom.'],
    ['ppi', 'PPI — wskaźnik cen producentów', 'Miara zmian cen otrzymywanych przez producentów za objętą badaniem produkcję; w Polsce typowym przykładem jest wskaźnik cen produkcji sprzedanej przemysłu.', 'Nie jest wskaźnikiem cen detalicznych ani wyłącznie cen surowców. Zakres zależy od statystyki.'],
    ['stagflation', 'Stagflacja', 'Współwystępowanie inflacji i stagnacji lub bardzo słabej aktywności gospodarczej, zwykle z wysokim bezrobociem.', 'Może być skutkiem negatywnego szoku podażowego.'],
    ['slumpflation', 'Slumpflacja', 'Współwystępowanie inflacji i spadku realnej produkcji, czyli recesji. Termin podkreśla głębszy spadek aktywności niż sama stagnacja.', 'Nie oznacza deflacji: poziom cen rośnie mimo kurczenia się produkcji.']
  ]);
  add('macro', 'demand', [
    ['phillips', 'Krzywa Phillipsa', 'W wersji krótkookresowej opisuje ujemną zależność między inflacją a bezrobociem przy danych oczekiwaniach inflacyjnych i szokach podażowych.', 'Pierwotnie dotyczyła wzrostu płac nominalnych. W modelu z dostosowującymi się oczekiwaniami długookresowa krzywa jest pionowa przy naturalnej stopie bezrobocia.', 'krzywa Philipsa'],
    ['demand-shock', 'Szok popytowy', 'Nieoczekiwana zmiana wydatków globalnych przy danym poziomie cen, przesuwająca krzywą zagregowanego popytu AD.', 'Dodatni szok zwykle zwiększa krótkookresowo produkcję i poziom cen, jeśli krótkookresowa AS jest rosnąca.'],
    ['supply-shock', 'Szok podażowy', 'Nieoczekiwana zmiana warunków produkcji, kosztów lub wydajności przesuwająca zagregowaną podaż AS.', 'Negatywny szok kosztowy zwykle zmniejsza produkcję i podnosi poziom cen w krótkim okresie.'],
    ['multiplier', 'Efekt mnożnikowy', 'Łączna zmiana dochodu równowagi wywołana zmianą wydatku autonomicznego może być większa niż ten wydatek, ponieważ powstające dochody uruchamiają kolejne wydatki.', 'W prostym modelu przy stałych cenach, wolnych mocach, bez podatków i importu mnożnik wydatków k = 1/(1 − MPC). Odpływy i reakcje cen lub stóp mogą osłabić efekt.']
  ]);
  add('policy', 'classical', [
    ['neutrality', 'Neutralność pieniądza', 'Własność modelu, zgodnie z którą jednorazowa proporcjonalna zmiana nominalnej podaży pieniądza zmienia wielkości nominalne, ale nie realną produkcję, zatrudnienie ani relacje cen.', 'Zwykle jest założeniem długookresowym. Neutralność nie oznacza superneutralności, dotyczącej zmiany tempa wzrostu podaży pieniądza.'],
    ['dichotomy', 'Klasyczna dychotomia', 'Rozdzielenie analizy gospodarki na sferę realną, wyznaczaną przez zasoby, technologię i preferencje, oraz nominalną, w której pieniądz wyznacza ogólny poziom cen.', 'Jest własnością określonych modeli; nie zakładaj jej bezwarunkowo w krótkim okresie.'],
    ['rational-expectations', 'Teoria racjonalnych oczekiwań', 'Hipoteza, że oczekiwania wykorzystują dostępną istotną informację i są zgodne ze strukturą modelu; błędy prognoz nie są systematycznie przewidywalne na tej podstawie.', 'Nie oznacza doskonałej wiedzy ani bezbłędnego przewidywania przyszłości.'],
    ['quantity-theory', 'Ilościowa teoria pieniądza', 'Teoria łącząca podaż pieniądza z poziomem cen na podstawie równania MV = PY. Przy stałej szybkości obiegu V i realnej produkcji Y wyznaczanej przez czynniki realne wzrost M podnosi P proporcjonalnie.', 'Samo MV = PY jest tożsamością przy odpowiedniej definicji V; wniosek przyczynowy wymaga dodatkowych założeń.']
  ]);
  add('policy', 'money', [
    ['money-multiplier', 'Mnożnik kreacji pieniądza', 'Relacja podaży pieniądza do bazy monetarnej. W modelu M = C + D, B = C + R wynosi m = (1 + c)/(c + r), gdzie c = C/D, a r = R/D obejmuje wszystkie rezerwy.', 'Uproszczone m = 1/rr wymaga braku gotówki poza bankami, braku nadwyżkowych rezerw i pełnego wykorzystania mechanizmu. Nie opisuje mechanicznie współczesnej akcji kredytowej.'],
    ['full-reserve', 'System rezerwy całkowitej', 'System, w którym określone depozyty, zwykle płatne na żądanie, mają stuprocentowe pokrycie rezerwami. W prostym modelu bank nie kreuje z nich dodatkowych depozytów przez kredytowanie.', 'Nie wyklucza kredytowania ze środków kapitałowych lub innych źródeł finansowania.'],
    ['fractional-reserve', 'System rezerwy cząstkowej', 'System bankowy, w którym rezerwy stanowią tylko część depozytów. Udzielaniu kredytu może towarzyszyć utworzenie depozytu na rachunku kredytobiorcy.', 'Akcję kredytową ograniczają także kapitał, płynność, ryzyko, popyt na kredyt i polityka pieniężna.'],
    ['bank-run', 'Run na bank', 'Masowe żądania wypłaty depozytów, wywołane obawą o bezpieczeństwo banku. Mogą spowodować kryzys płynności, ponieważ aktywa banku nie są w całości natychmiast zamienialne na gotówkę.', 'Problem płynności może dotknąć także bank wypłacalny.', 'panika bankowa']
  ]);
  add('policy', 'fiscal', [
    ['automatic', 'Automatyczne stabilizatory koniunktury', 'Elementy podatków i wydatków, które bez nowych decyzji władz łagodzą wahania dochodu i popytu, np. spadek wpływów podatkowych oraz wzrost wypłat zasiłków w recesji.', 'Działają według istniejących zasad, w odróżnieniu od nowych programów dyskrecjonalnych.'],
    ['budget-deficit', 'Deficyt budżetowy', 'Nadwyżka wydatków budżetu nad jego dochodami w danym okresie.', 'Deficyt jest strumieniem; dług publiczny jest zasobem zobowiązań. Zakres budżetu państwa i całego sektora instytucji rządowych i samorządowych może się różnić.'],
    ['private-saving', 'Oszczędności prywatne', 'Część dochodu sektora prywatnego, której nie przeznacza się na konsumpcję. W prostym modelu: Sp = Y − T − C, gdzie T oznacza podatki netto po transferach.', 'W bardziej szczegółowych rachunkach obejmują oszczędności gospodarstw domowych i przedsiębiorstw.'],
    ['public-saving', 'Oszczędności publiczne', 'W prostym modelu makroekonomicznym różnica między podatkami netto a zakupami państwa: Sg = T − G. Ujemna wartość oznacza nieoszczędzanie sektora publicznego.', 'W rachunkach narodowych oszczędności bieżące należy odróżnić od salda finansowego obejmującego także inwestycje publiczne.'],
    ['fiscal-policy', 'Polityka fiskalna', 'Oddziaływanie władz na gospodarkę przez dochody publiczne, wydatki i saldo sektora publicznego. Ekspansja może polegać na zwiększeniu zakupów państwa lub obniżeniu podatków.', 'Skutki zależą m.in. od koniunktury, sposobu finansowania i reakcji banku centralnego.'],
    ['monetary-policy', 'Polityka pieniężna', 'Działania banku centralnego wpływające na warunki pieniężne i finansowe w gospodarce za pomocą m.in. stóp procentowych, operacji rynkowych i zarządzania płynnością.', 'Oddziałuje na popyt, inflację i aktywność z opóźnieniem; nie jest tym samym co polityka podatkowa.'],
    ['crowding-out', 'Efekt wypierania', 'Zmniejszenie wydatków prywatnych, zwłaszcza inwestycji, wskutek ekspansji fiskalnej, np. gdy wzrost zapotrzebowania państwa na finansowanie podnosi realną stopę procentową.', 'Może być częściowy, pełny lub słaby; nie jest automatycznie jednakowy w każdych warunkach.'],
    ['inflation-tax', 'Podatek inflacyjny', 'Utrata realnej wartości posiadanych sald pieniężnych wskutek wzrostu poziomu cen, ekonomicznie obciążająca ich posiadaczy.', 'Nie jest formalnie uchwalonym podatkiem. Jest powiązany z senioratem, ale nie jest tożsamy z całym dochodem z emisji pieniądza.'],
    ['loanable', 'Rynek funduszy pożyczkowych', 'Model rynku, na którym podaż oszczędności i popyt na finansowanie wyznaczają realną stopę procentową. W prostym modelu gospodarki zamkniętej oszczędności narodowe finansują inwestycje.', 'Nie myl z rynkiem pieniądza. Deficyt można modelować jako spadek podaży oszczędności narodowych albo dodatkowy popyt państwa; nie licz go podwójnie.']
  ]);
  add('policy', 'taxflation', [
    ['taxflation', 'Taksflacja', 'Wzrost realnego ciężaru opodatkowania spowodowany inflacyjnym wzrostem nominalnych dochodów przy nieindeksowanych progach, ulgach lub kwotach wolnych, nawet bez wzrostu dochodu realnego.', 'Pełzanie przedziałowe: podatnik może trafić do wyższego progu tylko z powodu inflacji. Nie myl z podatkiem inflacyjnym od sald pieniężnych.', 'pełzanie przedziałowe fiscal drag']
  ]);
  add('world', 'trade', [
    ['absolute', 'Przewaga absolutna', 'Zdolność wytworzenia większej ilości dobra z tych samych zasobów albo tej samej ilości przy mniejszym ich nakładzie niż inny producent.', 'Porównuje bezwzględną produktywność, nie koszty alternatywne.', 'korzyści absolutne'],
    ['comparative', 'Przewaga komparatywna', 'Zdolność wytworzenia dobra przy niższym koszcie alternatywnym niż u innego producenta.', 'Korzyści z wymiany są możliwe także wtedy, gdy jeden kraj ma przewagę absolutną w obu dobrach, jeśli koszty względne są różne.', 'korzyści komparatywne przewaga względna'],
    ['heckscher-ohlin', 'Model Heckschera–Ohlina', 'Model wyjaśniający strukturę handlu różnicami we względnym wyposażeniu w czynniki: kraj eksportuje dobro intensywnie wykorzystujące czynnik, w który jest względnie obficie wyposażony.', 'Standardowo zakłada m.in. porównywalne technologie, konkurencję doskonałą, mobilność czynników wewnątrz kraju i brak ich mobilności między krajami.', 'model Heckschera-Ohlina Heckscher Ohlin'],
    ['leontief', 'Paradoks Leontiefa', 'Wynik badania gospodarki USA, w którym amerykański eksport okazał się mniej kapitałochłonny niż krajowa produkcja zastępująca import, wbrew prostemu przewidywaniu modelu Heckschera–Ohlina dla kraju obfitego w kapitał.', 'To wynik empiryczny zależny od pomiaru i założeń; nie dowodzi, że handel nie przynosi korzyści.'],
    ['trade-deficit', 'Deficyt handlowy', 'Sytuacja, w której wartość importu przewyższa wartość eksportu w danym okresie.', 'W statystyce saldo handlu towarami odróżnia się od salda towarów i usług oraz rachunku bieżącego; w modelach NX = X − M często obejmuje towary i usługi.'],
    ['net-capital-outflow', 'Odpływy kapitałowe netto', 'Nabycie zagranicznych aktywów przez rezydentów pomniejszone o nabycie aktywów krajowych przez nierezydentów. Dodatnie NCO oznacza finansowanie reszty świata netto.', 'W uproszczonym modelu bez dochodów i transferów zagranicznych NCO = NX = S − I. W pełnym bilansie płatniczym trzeba uwzględnić szersze salda i konwencję znaków.', 'NCO']
  ]);
  add('world', 'currency', [
    ['appreciation', 'Aprecjacja', 'Rynkowy wzrost wartości waluty względem innej waluty w systemie kursu płynnego.', 'Przy kwotowaniu PLN za EUR spadek kursu oznacza aprecjację złotego. Administracyjne podwyższenie parytetu to rewaluacja.'],
    ['depreciation', 'Deprecjacja', 'Rynkowy spadek wartości waluty względem innej waluty w systemie kursu płynnego.', 'Przy kwotowaniu PLN za EUR wzrost kursu oznacza deprecjację złotego. Administracyjne obniżenie parytetu to dewaluacja.'],
    ['ppp', 'Parytet siły nabywczej', 'Hipoteza, że kurs walut odzwierciedla relację poziomów cen. W wersji absolutnej E = Pk/Pz, gdy E oznacza liczbę jednostek waluty krajowej za jednostkę zagranicznej, a poziomy cen dotyczą porównywalnych koszyków.', 'Wersja względna: tempo deprecjacji waluty krajowej jest w przybliżeniu równe różnicy inflacji krajowej i zagranicznej. Bariery handlu i dobra niehandlowe ograniczają zgodność.', 'PPP teoria parytetu siły nabywczej']
  ]);
  add('world', 'prices', [
    ['fisher', 'Efekt Fishera', 'Przy niezmienionej realnej stopie procentowej wzrost oczekiwanej inflacji przekłada się na taki sam wzrost nominalnej stopy procentowej w przybliżeniu i ≈ r + πe.', 'Dokładnie: (1 + i) = (1 + r)(1 + πe). Oczekiwana inflacja służy ocenie ex ante, a zrealizowana — ex post.'],
    ['discounting', 'Dyskontowanie', 'Przeliczanie przyszłej wartości na wartość bieżącą za pomocą stopy dyskontowej. Przy stałej stopie i: PV = FV/(1 + i)^n.', 'Dopasuj stopę do okresu i do rodzaju przepływów: nominalne dyskontuje się stopą nominalną, realne — realną.'],
    ['fundamental', 'Analiza fundamentalna', 'Ocena wartości aktywa na podstawie czynników ekonomicznych, np. przyszłych przepływów pieniężnych, rentowności, zadłużenia i perspektyw branży oraz gospodarki.', 'Wynik jest oszacowaniem zależnym od założeń, a nie gwarancją przyszłej ceny.'],
    ['technical-analysis', 'Analiza techniczna', 'Analiza historycznych cen, wolumenu i innych danych rynkowych w celu identyfikacji trendów lub sygnałów dotyczących przyszłych zmian cen.', 'Nie wycenia przedsiębiorstwa przez jego przepływy pieniężne i nie zapewnia pewnych prognoz.']
  ]);
  sources.knf = ['KNF · Rynek kapitałowy i terminowy, s. 115–116', 'https://www.knf.gov.pl/knf/pl/komponenty/img/Rynek%20kapitalowy_25920.pdf'];
  sources.discounting = ['OpenStax · wartość pieniądza w czasie', 'https://openstax.org/books/contemporary-mathematics/pages/6-4-compound-interest'];
  sources.gusDnb = ['GUS · dochód narodowy brutto', 'https://stat.gov.pl/metainformacje/slownik-pojec/pojecia-stosowane-w-statystyce-publicznej/1050%2Cpojecie.html'];
  sources.allocation = ['G. Kozuń-Cieślak, SGH · efektywność techniczna i alokacyjna', 'https://cejsh.icm.edu.pl/cejsh/element/bwmeta1.element.ojs-doi-10_33119_KKESSiP_2013_4_1/c/178-159.pdf'];
  sources.ohlin = ['WTO · model Heckschera–Ohlina i paradoks Leontiefa', 'https://www.wto.org/english/res_e/booksp_e/anrep_e/wtr08-2c_e.pdf'];
  sources.technicalOptimum = ['WNE UW · koszty przedsiębiorstwa', 'https://coin.wne.uw.edu.pl/tkopczewski/MIKROsite/koszty.htm'];
  sources.deflatorGus = ['GUS · deflator produktu krajowego brutto', 'https://stat.gov.pl/metainformacje/opis-wskaznikow-gus/wielkosci-i-wskazniki-oglaszane-gus/deflator-produktu-krajowego-brutto/'];
