    if (item.id === 'ceteris') item.source = 'market';
    if (['isoquant', 'isocost', 'producer-optimum', 'mrts'].includes(item.id)) item.source = 'allocation';
    if (['heckscher-ohlin', 'leontief'].includes(item.id)) item.source = 'ohlin';
    if (['flexibility', 'expansibility'].includes(item.id)) item.source = 'wnorowski';
    if (item.id === 'technical-optimum') item.source = 'technicalOptimum';
